from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Tunable 2mm kernel.
# Additional size parameters (Ti, Tj, Tl) act as compile-time tile sizes
# that can be adjusted via partial evaluation for different cache hierarchies.
@proc
def kernel_2mm_tunable(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    Ti: size,              # currently unused but available for future i-tiling
    Tj: size,              # tile size for the nj dimension
    Tl: size,              # tile size for the nl dimension
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    tmp: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    C: DATA_TYPE[nj, nl] @ DRAM,
    D: DATA_TYPE[ni, nl] @ DRAM,
):
    # D := alpha * A * B * C + beta * D
    # Basic shape assertions to keep the kernel well-defined.
    assert ni > 0
    assert nj > 0
    assert nk > 0
    assert nl > 0
    assert Tj > 0
    assert Tl > 0

    # ------------------------------------------------------------------
    # Phase 1: tmp = alpha * A * B
    #
    # We first zero the entire row tmp[i, :]
    # and then, for each k, update the full row using:
    #   tmp[i, j] += alpha * A[i, k] * B[k, j]
    #
    # The inner j-dimension is explicitly tiled by Tj to improve locality
    # when streaming over B[k, j] and tmp[i, j].
    # ------------------------------------------------------------------
    for i in seq(0, ni):
        # Zero out row i of tmp once, outside the k-loop.
        for j in seq(0, nj):
            tmp[i, j] = 0.0

        for k in seq(0, nk):
            aik: DATA_TYPE
            aik = alpha * A[i, k]

            # Main tiled part over j in blocks of size Tj.
            for jj in seq(0, nj / Tj):
                for tj in seq(0, Tj):
                    tmp[i, jj * Tj + tj] += aik * B[k, jj * Tj + tj]

            # Remainder loop for the tail when nj is not divisible by Tj.
            for j in seq(Tj * (nj / Tj), nj):
                tmp[i, j] += aik * B[k, j]

    # ------------------------------------------------------------------
    # Phase 2: D = beta * D + tmp * C
    #
    # We scale row i of D by beta once, then for each k we accumulate:
    #   D[i, j] += tmp[i, k] * C[k, j]
    #
    # The nl-dimension is tiled by Tl to improve locality when streaming
    # over C[k, j] and D[i, j].
    # ------------------------------------------------------------------
    for i in seq(0, ni):
        # Scale D by beta.
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]

        for k in seq(0, nj):
            tik: DATA_TYPE
            tik = tmp[i, k]

            # Main tiled part over j in blocks of size Tl.
            for ll in seq(0, nl / Tl):
                for tl in seq(0, Tl):
                    D[i, ll * Tl + tl] += tik * C[k, ll * Tl + tl]

            # Remainder loop for the tail when nl is not divisible by Tl.
            for j in seq(Tl * (nl / Tl), nl):
                D[i, j] += tik * C[k, j]


