    # First matrix product: tmp = alpha * A * B.
    # Loop order is initially i-j-k for clarity; we will schedule it below.
    for i in seq(0, ni):
        for j in seq(0, nj):
            tmp[i, j] = 0.0
            for k in seq(0, nk):
                tmp[i, j] += alpha * A[i, k] * B[k, j]

    # Second matrix product and accumulation: D = beta * D + tmp * C.
    for i in seq(0, ni):
        for j in seq(0, nl):
            D[i, j] = beta * D[i, j]
            for k in seq(0, nj):
                D[i, j] += tmp[i, k] * C[k, j]


