#     for i:
#       for j: tmp[i,j] = 0
#       for j: for k: tmp[i,j] += ...
tmp_init = p.find("tmp[_, _] = _")
p = fission(p, tmp_init.after(), n_lifts=1)

# 1b) In the accumulation loop, reorder (j, k) -> (k, j) to make j innermost.
#     This yields:
#       for i:
#         for k:
#           for j: tmp[i,j] += alpha*A[i,k]*B[k,j]
#     which traverses B[k, j] and tmp[i, j] with contiguous j indices.
k_loop_tmp = p.find_loop("k")       # first k-loop: accumulation into tmp
j_outer_tmp = k_loop_tmp.parent()   # its immediate enclosing j-loop
p = reorder_loops(p, j_outer_tmp)

# ---------------------------------------------------------------------------
# 2) Improve locality in the second GEMM (D = beta * D + tmp * C).
#    Again, separate scaling of D from the accumulation and reorder so that
#    we traverse the last (contiguous) dimension innermost.
# ---------------------------------------------------------------------------

# 2a) Fission the inner j-loop so that:
#     for i:
#       for j: D[i,j] = beta * D[i,j]
#       for j: for k: D[i,j] += tmp[i,k]*C[k,j]
beta_update = p.find("D[_, _] = _")
p = fission(p, beta_update.after(), n_lifts=1)

