#     for i:
#       for k:
#         for j: D[i,j] += tmp[i,k] * C[k,j]
#     which keeps accesses to C[k, j] and D[i, j] contiguous in j.
k_loop_D = p.find_loop("k #1")      # second k-loop: accumulation into D
j_outer_D = k_loop_D.parent()
p = reorder_loops(p, j_outer_D)

