#    Parallelize the compute-heavy outer i-loops of the two GEMMs.
#    We detect i-loops whose first statement is a k-loop; these correspond
#    exactly to the accumulation phases after the transformations above.
# ---------------------------------------------------------------------------

i_loops = p.find_loop("i", many=True)
for i_loop in i_loops:
